[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$AsrDataRoot,[Parameter(Mandatory=$true)][string]$AsrProgramRoot,[Parameter(Mandatory=$true)][string]$AsrBackupRoot,[Parameter(Mandatory=$true)][string]$RuntimeRoot,[Parameter(Mandatory=$true)][string]$ReportPath)
Set-StrictMode -Version Latest; $ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'asr-release.ps1')
$data=[IO.Path]::GetFullPath($AsrDataRoot).TrimEnd('\');$program=[IO.Path]::GetFullPath($AsrProgramRoot).TrimEnd('\');$backup=[IO.Path]::GetFullPath($AsrBackupRoot).TrimEnd('\');$runtime=[IO.Path]::GetFullPath($RuntimeRoot).TrimEnd('\')
$active=$null;$ap=Join-Path $data 'release-state\active.json';if(Test-Path $ap){$active=Get-Content $ap -Raw|ConvertFrom-Json};$refs=@{}
foreach($p in @(Get-ChildItem $backup -Filter candidate-activation-state.json -File -Recurse -Force -ErrorAction SilentlyContinue)){$s=Get-Content $p.FullName -Raw|ConvertFrom-Json;$id=Split-Path (Split-Path $p.FullName -Parent) -Leaf;foreach($c in @('candidate_id','previous_candidate_id')){if($s.PSObject.Properties.Name -contains $c -and $s.$c){$k=[string]$s.$c;if(!$refs.ContainsKey($k)){$refs[$k]=@()};$refs[$k]+=$id}}}
$asr=@();foreach($d in @(Get-ChildItem (Join-Path $program 'releases') -Directory -Force -ErrorAction SilentlyContinue)){ $id=$d.Name;$r=@();$status='eligible';$m=Join-Path $d.FullName 'release-manifest.json';$c=Join-Path $data "config\releases\$id\asr.env";$sha=$null;$valid=$false;if($active -and [string]$active.candidate_id -eq $id){$status='protected';$r+='active-candidate'};if($refs.ContainsKey($id)){$status='protected';$r+='activation-reference'};if(!(Test-Path $m)){ $status='invalid';$r+='manifest-missing'}else{try{$sha=(Get-FileHash $m -Algorithm SHA256).Hash.ToLowerInvariant();Read-AsrReleaseManifest -ProgramRoot $program -DataRoot $data -CandidateId $id -AllowLegacyWhisperXV1Profiles|Out-Null;$valid=$true}catch{$status='invalid';$r+='manifest-invalid'}};if(!(Test-Path $c)){$status='invalid';$r+='config-missing'};$asr+=[ordered]@{id=$id;path=$d.FullName;status=$status;reasons=$r;manifest_sha256=$sha;manifest_valid=$valid;config_path=$c;activation_ids=@($refs[$id])}}
$gpu=@();foreach($d in @(Get-ChildItem (Join-Path $runtime 'releases') -Directory -Force -ErrorAction SilentlyContinue)){ $m=Join-Path $d.FullName 'runtime-manifest.json';$r=@();$status='eligible';$sha=$null;$valid=$false;if(!(Test-Path $m)){$status='invalid';$r+='manifest-missing'}else{try{$sha=(Get-FileHash $m -Algorithm SHA256).Hash.ToLowerInvariant();$o=Get-Content $m -Raw|ConvertFrom-Json;if(!$o.schema_version){throw 'schema-missing'};$valid=$true}catch{$status='invalid';$r+='manifest-invalid'}};$gpu+=[ordered]@{id=$d.Name;path=$d.FullName;status=$status;reasons=$r;manifest_sha256=$sha;manifest_valid=$valid}}
$out=[ordered]@{schema_version='asr-runtime-release-audit/1';generated_at_utc=[DateTimeOffset]::UtcNow.ToString('o');destructive_operations_executed=$false;active_candidate_id=if($active){[string]$active.candidate_id}else{$null};asr_releases=$asr;gpu_runtime_releases=$gpu};New-Item (Split-Path $ReportPath -Parent) -ItemType Directory -Force|Out-Null;$out|ConvertTo-Json -Depth 12|Set-Content $ReportPath -Encoding UTF8
